scripts.codigo:
extends ForjaGameplayScript

var dentro: bool = false
var e_antes: bool = false
var vel: float = 0.0
var t_ruido: float = 0.0

func _quadro(dt: float) -> void:
	var j: Node3D = gp.jogador()
	if j == null or not no.visible:
		return
	var e: bool = Input.is_key_pressed(KEY_E)
	var apertou: bool = e and not e_antes
	e_antes = e
	if not dentro:
		if apertou and j.global_position.distance_to(no.global_position) < 3.0:
			dentro = true
			gp.msg("wasd dirige. e sai")
		return
	if apertou and absf(vel) < 1.0:
		dentro = false
		j.global_position = no.global_position + no.global_transform.basis.x * 2.0
		j.visible = true
		return
	var acel: float = 0.0
	if Input.is_key_pressed(KEY_W):
		acel += 1.0
	if Input.is_key_pressed(KEY_S):
		acel -= 0.5
	vel = move_toward(vel, acel * 9.0, dt * 6.0)
	var giro: float = 0.0
	if Input.is_key_pressed(KEY_A):
		giro += 1.0
	if Input.is_key_pressed(KEY_D):
		giro -= 1.0
	no.rotate_y(giro * dt * 2.0 * clampf(vel / 9.0, -1.0, 1.0))
	var frente: Vector3 = -no.global_transform.basis.z
	no.global_position += frente * vel * dt
	j.global_position = no.global_position
	j.visible = false
	for f: Node3D in gp.elementos("farois"):
		f.global_position = no.global_position + frente * 2.0 + Vector3.UP * 0.8
		f.global_rotation = no.global_rotation
	t_ruido -= dt
	if t_ruido <= 0.0:
		t_ruido = 1.0
		gp.ruido(no.global_position, 20.0 + absf(vel) * 3.0)
	for s: Node3D in gp.elementos("saida_estrada"):
		if s.visible and s.global_position.distance_to(no.global_position) < 3.5:
			j.visible = true
			gp.vitoria()
